SourceCode.Declaration:
/// <summary>
/// Extension of the <c>InventLocation</c> table for the AAXBlindReceiving model. Requires a blind
/// receipt pool on a warehouse that has blind PO receiving turned on.
/// </summary>
[ExtensionOf(tableStr(InventLocation))]
final class InventLocation_AAXBlindReceiving_Extension
{
}

Method.Source:
/// <summary>
/// Extends <c>validateWrite</c> to refuse a warehouse that has blind PO receiving turned on
/// without a blind receipt pool, after the base implementation is called with <c>next</c>.
/// </summary>
/// <returns>True if the record is valid; otherwise, false.</returns>
public boolean validateWrite()
{
    boolean ret = next validateWrite();

    if (ret
        && this.AAXBlindReceiptEnabled
        && !this.AAXBlindReceiptPurchPoolId)
    {
        ret = checkFailed(strFmt("@AAXBlindReceiving:ErrNoPool", this.InventLocationId));
    }

    return ret;
}
